-- 0176: Dandadan — den Spitznamen „Okarun“ gab Momo selbst; sein echter Name Ken Takakura
-- ist der ihres Lieblingsschauspielers. Idempotent.
update question_translations set explanation = 'Momo gave him the nickname because his real name, Ken Takakura, is that of her favourite actor.' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo le puso el apodo porque su nombre real, Ken Takakura, es el de su actor favorito.' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo lui a donné ce surnom, car son vrai nom, Ken Takakura, est celui de son acteur préféré.' where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo deu o apelido a ele porque seu nome verdadeiro, Ken Takakura, é o do ator favorito dela.' where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo gli diede il soprannome perché il suo vero nome, Ken Takakura, è quello del suo attore preferito.' where lang = 'it' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo memberinya julukan itu karena nama aslinya, Ken Takakura, sama dengan aktor favoritnya.' where lang = 'id' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo ona bu lakabı taktı, çünkü gerçek adı Ken Takakura, en sevdiği oyuncunun adıdır.' where lang = 'tr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo nadała mu ten przydomek, bo jego prawdziwe imię, Ken Takakura, nosi jej ulubiony aktor.' where lang = 'pl' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo đặt biệt danh này vì tên thật của cậu, Takakura Ken, trùng với diễn viên cô yêu thích.' where lang = 'vi' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = '本名の高倉健が憧れの俳優と同じ名前なので、モモが「オカルン」と呼ぶことにしました。' where lang = 'ja' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = '본명 다카쿠라 켄이 모모가 좋아하는 배우와 같은 이름이라 모모가 붙인 별명이에요.' where lang = 'ko' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'โมโมะตั้งชื่อเล่นนี้ให้ เพราะชื่อจริงของเขาคือทาคาคุระ เคน ซึ่งตรงกับดาราคนโปรดของเธอ' where lang = 'th' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Это прозвище дала ему Момо: его настоящее имя, Кэн Такакура, совпадает с именем её любимого актёра.' where lang = 'ru' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'أطلقت عليه مومو هذا اللقب لأن اسمه الحقيقي، كين تاكاكورا، هو اسم ممثلها المفضل.' where lang = 'ar' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
update question_translations set explanation = 'Momo gab ihm den Spitznamen, weil sein echter Name Ken Takakura der ihres Lieblingsschauspielers ist.' where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Wovon leitet sich der Spitzname „Okarun“ in Dandadan ab?');
